package replay

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"sort"
	"strings"
	"sync"
	"time"
)

// ReplayState represents the current state of a replay run
//go:generate stringer -type=ReplayState

type ReplayState string

const (
	StateRunning ReplayState = "running"
	StateStopped ReplayState = "stopped"
	StateFailed  ReplayState = "failed"
)

// Stats holds statistics data for a replay run
// p95ms is the 95th percentile latency in milliseconds
// We store latencies in a slice to compute p95

type Stats struct {
	Requests       int64   `json:"requests"`
	Errors         int64   `json:"errors"`
	LatencySamples []int64 // latency samples in ms
	p95ms          int64
	mu             sync.Mutex
}

// AddSample adds a latency sample (in milliseconds) and updates counters.
func (s *Stats) AddSample(latencyMs int64, isError bool) {
	s.mu.Lock()
	defer s.mu.Unlock()

	s.Requests++
	if isError {
		s.Errors++
	}
	// Only store samples of successful requests for latency calc
	if !isError {
		s.LatencySamples = append(s.LatencySamples, latencyMs)
	}
}

// CalculateP95 calculates the 95th percentile latency from stored samples
func (s *Stats) CalculateP95() {
	s.mu.Lock()
	defer s.mu.Unlock()

	if len(s.LatencySamples) == 0 {
		s.p95ms = 0
		return
	}

	// Copy and sort to find p95
	samples := make([]int64, len(s.LatencySamples))
	copy(samples, s.LatencySamples)
	sort.Slice(samples, func(i, j int) bool {
		return samples[i] < samples[j]
	})

	idx := int(float64(len(samples))*0.95)
	if idx >= len(samples) {
		idx = len(samples) - 1
	}
	s.p95ms = samples[idx]
}

// P95 returns the last computed p95 latency
func (s *Stats) P95() int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.p95ms
}

// Run represents a single replay execution
// Stores state, start time, and stats

type Run struct {
	RunID     string
	State     ReplayState
	StartedAt time.Time
	Stats     *Stats
	mu        sync.Mutex
	// control
	cancel context.CancelFunc
}

func NewRun(runID string) *Run {
	return &Run{
		RunID:     runID,
		State:     StateRunning,
		StartedAt: time.Now().UTC(),
		Stats:     &Stats{},
	}
}

// MarkStopped marks the run as stopped
func (r *Run) MarkStopped() {
	// Mark as stopped only if running
	// Cancel the context if any
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.State == StateRunning {
		r.State = StateStopped
		if r.cancel != nil {
			r.cancel()
		}
	}
}

// MarkFailed marks the run as failed
func (r *Run) MarkFailed() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.State = StateFailed
	if r.cancel != nil {
		r.cancel()
	}
}

// AddSample adds a latency sample and error flag to stats
func (r *Run) AddSample(latencyMs int64, isError bool) {
	r.Stats.AddSample(latencyMs, isError)
}

// UpdateP95 recalculates the p95 for the run stats
func (r *Run) UpdateP95() {
	r.Stats.CalculateP95()
}

// StatusResponse returns the JSON-compatible status response
func (r *Run) StatusResponse() map[string]interface{} {
	return map[string]interface{}{
		"runId":     r.RunID,
		"state":     r.State,
		"startedAt": r.StartedAt.Format(time.RFC3339),
		"stats": map[string]interface{}{
			"requests": r.Stats.Requests,
			"errors":   r.Stats.Errors,
			"p95ms":    r.Stats.P95(),
		},
	}
}

// Runner manages active replay runs
// Stores runs in memory mapped by runID

type Runner struct {
	runs map[string]*Run
	mu   sync.Mutex
	httpClient *http.Client
}

type StartParams struct {
	ScenarioID    string
	TargetBaseURL string
	RPS           int
	Duration      time.Duration
}

type StatusStats struct {
	Requests int64 `json:"requests"`
	Errors   int64 `json:"errors"`
	P95ms    int64 `json:"p95ms"`
}

type Status struct {
	RunID     string      `json:"runId"`
	State     ReplayState `json:"state"`
	StartedAt string      `json:"startedAt"`
	Stats     StatusStats `json:"stats"`
}

func NewRunner() *Runner {
	return &Runner{
		runs: make(map[string]*Run),
		httpClient: &http.Client{Timeout: 10 * time.Second},
	}
}

func (r *Runner) Start(params StartParams) (string, error) {
	if strings.TrimSpace(params.TargetBaseURL) == "" {
		return "", errors.New("targetBaseUrl is required")
	}
	if params.RPS <= 0 {
		return "", errors.New("rps must be > 0")
	}
	if params.Duration <= 0 {
		return "", errors.New("duration must be > 0")
	}

	runID := fmt.Sprintf("run-%d", time.Now().UTC().UnixNano())

	// Create run and start the goroutine
	run := NewRun(runID)
	ctx, cancel := context.WithCancel(context.Background())
	run.cancel = cancel

	r.mu.Lock()
	r.runs[runID] = run
	r.mu.Unlock()

	go r.runLoad(ctx, run, params)

	return runID, nil
}

func (r *Runner) runLoad(ctx context.Context, run *Run, params StartParams) {
	targetURL := strings.TrimRight(params.TargetBaseURL, "/") + "/debug/echo"

	rps := params.RPS
	dur := params.Duration

	interval := time.Second / time.Duration(rps) // spacing between requests
	if interval == 0 {
		interval = time.Millisecond * 1
	}

	end := time.Now().Add(dur)

	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			run.MarkStopped()
			return
		case now := <-ticker.C:
			if now.After(end) {
				// Time exceeded stop run
				run.MarkStopped()
				return
			}

			start := time.Now()

			resp, err := r.httpClient.Get(targetURL)
			latencyMs := time.Since(start).Milliseconds()

			if err != nil {
				// Record error sample
				run.AddSample(0, true)
				continue
			}

			_ = resp.Body.Close()

			if resp.StatusCode < 200 || resp.StatusCode >= 300 {
				// Non 2xx status
				run.AddSample(latencyMs, true)
				continue
			}

			// success
			run.AddSample(latencyMs, false)
		}
	}
}

func (r *Runner) Stop(runID string) error {
	if strings.TrimSpace(runID) == "" {
		return errors.New("runId is required")
	}
	if ok := r.StopRun(runID); !ok {
		return errors.New("run not found")
	}
	return nil
}

func (r *Runner) Status(runID string) (Status, error) {
	if strings.TrimSpace(runID) == "" {
		return Status{}, errors.New("runId is required")
	}
	run, ok := r.GetRun(runID)
	if !ok {
		return Status{}, errors.New("run not found")
	}

	// Calculate latest p95
	// Defensive: run.Stats.CalculateP95()
	run.UpdateP95()

	// Snapshot values
	run.Stats.mu.Lock()
	requests := run.Stats.Requests
	errorsCount := run.Stats.Errors
	p95 := run.Stats.p95ms
	run.Stats.mu.Unlock()

	return Status{
		RunID:     run.RunID,
		State:     run.State,
		StartedAt: run.StartedAt.Format(time.RFC3339),
		Stats: StatusStats{
			Requests: requests,
			Errors:   errorsCount,
			P95ms:    p95,
		},
	}, nil
}

// StartRun creates and stores a new run
func (r *Runner) StartRun(runID string) *Run {
	r.mu.Lock()
	defer r.mu.Unlock()
	run := NewRun(runID)
	r.runs[runID] = run
	return run
}

// StopRun marks a run as stopped and cancels its context
func (r *Runner) StopRun(runID string) bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	run, ok := r.runs[runID]
	if !ok {
		return false
	}
	run.MarkStopped()
	return true
}

// GetRun fetches a run by ID
func (r *Runner) GetRun(runID string) (*Run, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	run, ok := r.runs[runID]
	return run, ok
}

// Simulate recording a latency sample or error (for usage)
// This is just an example; actual runner would call AddSample
func (r *Runner) RecordSample(runID string, latencyMs int64, isError bool) {
	if run, ok := r.GetRun(runID); ok {
		run.AddSample(latencyMs, isError)
	}
}

// PeriodicUpdate updates p95 for all runs - should be called periodically
func (r *Runner) PeriodicUpdate() {
	r.mu.Lock()
	runs := make([]*Run, 0, len(r.runs))
	for _, run := range r.runs {
		runs = append(runs, run)
	}
	r.mu.Unlock()

	for _, run := range runs {
		run.UpdateP95()
	}
}

package replay

import (
	"sync"
	"testing"
	"time"
)

func TestStartValidation(t *testing.T) {
	r := NewRunner()

	if _, err := r.Start(StartParams{TargetBaseURL: "", RPS: 1, Duration: time.Second}); err == nil {
		t.Fatalf("expected error for empty target")
	}
	if _, err := r.Start(StartParams{TargetBaseURL: "http://x", RPS: 0, Duration: time.Second}); err == nil {
		t.Fatalf("expected error for rps")
	}
	if _, err := r.Start(StartParams{TargetBaseURL: "http://x", RPS: 1, Duration: 0}); err == nil {
		t.Fatalf("expected error for duration")
	}
}

func TestStartStopStatus(t *testing.T) {
	r := NewRunner()

	id, err := r.Start(StartParams{TargetBaseURL: "http://x", RPS: 1, Duration: time.Second})
	if err != nil {
		t.Fatalf("start err: %v", err)
	}

	st, err := r.Status(id)
	if err != nil || st.State != "running" {
		t.Fatalf("status expected running, got %+v err=%v", st, err)
	}

	if err := r.Stop(id); err != nil {
		t.Fatalf("stop err: %v", err)
	}

	st, _ = r.Status(id)
	if st.State != "stopped" {
		t.Fatalf("expected stopped, got %s", st.State)
	}
}

func TestStatsAddSampleConcurrent(t *testing.T) {
	run := NewRun("test-run")

	wg := sync.WaitGroup{}
	n := 1000

	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			latencyMs := int64(i % 100)
			isError := i%10 == 0
			run.AddSample(latencyMs, isError)
		}(i)
	}
	wg.Wait()

	if run.Stats.Requests != int64(n) {
		t.Fatalf("expected %d requests, got %d", n, run.Stats.Requests)
	}
	expectedErrors := int64(n / 10)
	if run.Stats.Errors != expectedErrors {
		t.Fatalf("expected %d errors, got %d", expectedErrors, run.Stats.Errors)
	}

	// Check latency samples count
	if len(run.Stats.LatencySamples) != n-int(expectedErrors) {
		t.Fatalf("expected %d latency samples, got %d", n-int(expectedErrors), len(run.Stats.LatencySamples))
	}
}

func TestCalculateP95(t *testing.T) {

	stats := &Stats{}

	// Add 100 samples 1..100 ms
	for i := int64(1); i <= 100; i++ {
		stats.AddSample(i, false)
	}

	stats.CalculateP95()

	if stats.p95ms != 95 {
		t.Fatalf("expected p95 95, got %d", stats.p95ms)
	}

	// Add some errors, should not affect latency samples
	for i := 0; i < 10; i++ {
		stats.AddSample(0, true)
	}

	stats.CalculateP95()

	if stats.p95ms != 95 {
		t.Fatalf("expected p95 95 after errors, got %d", stats.p95ms)
	}
}
